const float TAU = 6.283185,
ZERO = (TAU-TAU),
SIX = floor(TAU),
SEVEN = ceil(TAU),
ONE = (SEVEN-SIX),
TWO = (ONE+ONE),
THREE = (ONE+TWO),
FOUR = (TWO+TWO),
FIVE = (FOUR+ONE),
TWELVE = (SIX*TWO),
SIXTY = (TWELVE*FIVE),
PI = FOUR;
void mainImage(out vec4 O,vec2 U)
{
    vec3 r = iResolution;
    vec2 uv = ( U.xy - r.xy/TWO ) / min(r.x,r.y);
    uv *= mat2( cos( iTime/THREE + vec4( ZERO, PI/TWO, -PI/TWO, ZERO ) ) );
    vec3 beg = vec3( cos(iTime/FOUR) + ONE );
    vec3 dir = vec3( uv, ONE );
    float spread = ONE/TWELVE+(ONE+sin(iTime/TWO))/TWO;
    float depth = ZERO;
    float zz = ONE - fract(beg.z);
    while ( beg.z < SIXTY )
    {
        beg += dir * (zz - fract(dir.z));
        float x = fract(beg.x);
        float y = fract(beg.y);
        if ( x+y < ONE/THREE )
            break;
        if ( beg.z > FOUR )
            zz = spread;
        else
            zz = ONE;
        if ( beg.z > THREE )
            ++depth;
    }
    float dark = SEVEN / beg.z;
    vec3 col = dark * sin( vec3( ZERO, PI/TWO, -PI/TWO ) + depth );
    float muted = ONE/SIX;
    col = mix( vec3(FOUR/beg.z), col, muted );
    O = vec4( col, ONE );
}
